INSERT INTO cms_variables (key, value, category) VALUES ('web.layout.footer.aboutText', 'Vítejte u Motogo24, vaší <strong>půjčovny motorek v Pelhřimově</strong>! Nabízíme <strong>pronájem motorek</strong> pro místní i turisty. Vyberte si z nabídky sportovních nebo enduro motorek a rezervujte online ve třech krocích.', 'web') ON CONFLICT (key) DO NOTHING;
