INSERT INTO cms_variables (key, value, category) VALUES ('web.home.seo.title', 'Půjčovna motorek na Vysočině | MotoGo24', 'web') ON CONFLICT (key) DO NOTHING;
INSERT INTO cms_variables (key, value, category) VALUES ('web.home.seo.description', 'Půjčte si motorku na Vysočině. Bez kauce, výbava v ceně, nonstop provoz. Cestovní, sportovní, enduro i dětské motorky. Online rezervace.', 'web') ON CONFLICT (key) DO NOTHING;
INSERT INTO cms_variables (key, value, category) VALUES ('web.home.seo.keywords', 'půjčovna motorek Vysočina, pronájem motorek Pelhřimov, půjčovna motorek bez kauce, nonstop půjčovna, motorky k pronájmu, online rezervace motorky', 'web') ON CONFLICT (key) DO NOTHING;
