INSERT INTO cms_variables (key, value, category) VALUES ('web.home.hero.body', 'Půjč si motorku na Vysočině snadno online.<br>Vyber si z cestovních, sportovních i enduro modelů.<br>Rezervace s platbou kartou a rychlým převzetím.', 'web') ON CONFLICT (key) DO NOTHING;
