INSERT INTO cms_variables (key, value, category) VALUES ('web.home.h1', 'Půjčovna motorek Vysočina Motogo24 – bez kauce a nonstop', 'web') ON CONFLICT (key) DO NOTHING;
INSERT INTO cms_variables (key, value, category) VALUES ('web.home.intro', 'Vítejte v <strong>Motogo24</strong> – vaší půjčovně motorek na Vysočině. U nás si půjčíte motorku <strong>bez kauce</strong>, s výbavou v ceně a v režimu <strong>nonstop</strong>. Ať hledáte cestovní, sportovní, enduro nebo dětskou motorku, Motogo24 vám v srdci Vysočiny nabídne motorku na míru.', 'web') ON CONFLICT (key) DO NOTHING;
