INSERT INTO cms_variables (key, value, category) VALUES ('web.jak_pujcit_pristaveni.cta.text', 'Motogo24 nabízí přistavení motocyklu po regionu i mimo něj. Nonstop provoz, bez kauce, výbava v ceně.', 'web') ON CONFLICT (key) DO NOTHING;
