INSERT INTO cms_variables (key, value, category) VALUES ('web.pujcovna.faq.items.0.q', 'Jak si mohu rezervovat motorku?', 'web') ON CONFLICT (key) DO NOTHING;
INSERT INTO cms_variables (key, value, category) VALUES ('web.pujcovna.faq.items.0.a', 'Motorku si můžeš rezervovat přes náš online rezervační systém přímo tady na webu. Případně se nám můžeš ozvat e-mailem, telefonicky nebo přes naše sociální sítě.', 'web') ON CONFLICT (key) DO NOTHING;
INSERT INTO cms_variables (key, value, category) VALUES ('web.pujcovna.faq.items.1.q', 'Můžu si motorku půjčit i bez předchozí rezervace?', 'web') ON CONFLICT (key) DO NOTHING;
INSERT INTO cms_variables (key, value, category) VALUES ('web.pujcovna.faq.items.1.a', 'Bez rezervace to bohužel nejde. Každou motorku je nutné předem zamluvit.', 'web') ON CONFLICT (key) DO NOTHING;
INSERT INTO cms_variables (key, value, category) VALUES ('web.pujcovna.faq.items.2.q', 'Musím složit kauci?', 'web') ON CONFLICT (key) DO NOTHING;
INSERT INTO cms_variables (key, value, category) VALUES ('web.pujcovna.faq.items.2.a', 'Ne! U nás <strong>žádnou kauci platit nemusíš</strong>. Naše půjčovna se tímto zásadně liší od většiny konkurence.', 'web') ON CONFLICT (key) DO NOTHING;
INSERT INTO cms_variables (key, value, category) VALUES ('web.pujcovna.faq.items.3.q', 'Můžu odcestovat s motorkou do zahraničí?', 'web') ON CONFLICT (key) DO NOTHING;
INSERT INTO cms_variables (key, value, category) VALUES ('web.pujcovna.faq.items.3.a', 'Ano, s motorkou můžeš bez problémů vyrazit i do zahraničí. Cesty mimo Česko neomezujeme, jen je potřeba dodržet územní platnost pojištění (zelená karta).', 'web') ON CONFLICT (key) DO NOTHING;
INSERT INTO cms_variables (key, value, category) VALUES ('web.pujcovna.cta.title', 'Rezervuj svou motorku online', 'web') ON CONFLICT (key) DO NOTHING;
INSERT INTO cms_variables (key, value, category) VALUES ('web.pujcovna.cta.text', 'Naše <strong>půjčovna motorek Vysočina</strong> je otevřená <strong>nonstop</strong>. Stačí pár kliků a tvoje jízda začíná.', 'web') ON CONFLICT (key) DO NOTHING;
INSERT INTO cms_variables (key, value, category) VALUES ('web.pujcovna.cta.buttons.0.label', 'REZERVOVAT MOTORKU', 'web') ON CONFLICT (key) DO NOTHING;
INSERT INTO cms_variables (key, value, category) VALUES ('web.pujcovna.cta.buttons.1.label', 'Dárkový poukaz', 'web') ON CONFLICT (key) DO NOTHING;
