INSERT INTO cms_variables (key, value, category) VALUES ('web.jak_pujcit.intro', 'V Motogo24 – půjčovna motorek na Vysočině je půjčení jednoduché, rychlé a férové.', 'web') ON CONFLICT (key) DO NOTHING;
