INSERT INTO cms_variables (key, value, category) VALUES ('web.layout.editRez.description', 'Upravte termín, prodlužte, zkraťte nebo zrušte svou rezervaci. Vrácení peněz dle storno podmínek.', 'web') ON CONFLICT (key) DO NOTHING;
