INSERT INTO cms_variables (key, value, category) VALUES ('web.layout.editRez.extend.help', 'V kalendáři klikněte na den před původním začátkem (vyzvednutí dříve) nebo na den po původním konci (vrácení později). Zaplatíte pouze rozdíl ceny.', 'web') ON CONFLICT (key) DO NOTHING;
INSERT INTO cms_variables (key, value, category) VALUES ('web.layout.editRez.extend.helpUpcoming', 'V kalendáři klikněte na den před začátkem rezervace (vyzvednutí dříve) nebo na den po jejím konci (vrácení později). Můžete prodloužit obě strany — opětovným kliknutím na prodloužený okraj výběr zrušíte.', 'web') ON CONFLICT (key) DO NOTHING;
INSERT INTO cms_variables (key, value, category) VALUES ('web.layout.editRez.extend.helpActive', 'U probíhající rezervace lze prodloužit jen vrácení. V kalendáři klikněte na den po původním konci.', 'web') ON CONFLICT (key) DO NOTHING;
