INSERT INTO cms_variables (key, value, category) VALUES ('web.layout.editRez.shorten.title', 'Zkrátit rezervaci', 'web') ON CONFLICT (key) DO NOTHING;
INSERT INTO cms_variables (key, value, category) VALUES ('web.layout.editRez.shorten.help', 'Vyberte stranu (Začátek nebo Konec) a v kalendáři klikněte uvnitř rezervace na nový den. Vracíme peníze podle storno podmínek.', 'web') ON CONFLICT (key) DO NOTHING;
INSERT INTO cms_variables (key, value, category) VALUES ('web.layout.editRez.shorten.helpUpcoming', 'Vyberte tlačítkem nahoře, jestli chcete zkrátit Začátek (pozdější vyzvednutí) nebo Konec (dřívější vrácení). Pak v kalendáři klikněte uvnitř rezervace na nový den. Opětovný klik na zkrácený okraj výběr zruší.', 'web') ON CONFLICT (key) DO NOTHING;
INSERT INTO cms_variables (key, value, category) VALUES ('web.layout.editRez.shorten.helpActive', 'U probíhající rezervace lze zkrátit jen vrácení. V kalendáři klikněte na den před původním koncem (a ne dříve než dnešek).', 'web') ON CONFLICT (key) DO NOTHING;
INSERT INTO cms_variables (key, value, category) VALUES ('web.layout.editRez.shorten.helpUpcomingLong', 'Vyberte stranu, kterou chcete zkrátit (Začátek = pozdější vyzvednutí, Konec = dřívější vrácení), pak klikněte v kalendáři uvnitř rezervace na nový den. Refund podle storno podmínek.', 'web') ON CONFLICT (key) DO NOTHING;
