INSERT INTO cms_variables (key, value, category) VALUES ('web.layout.editRez.loc.help', 'Změňte způsob, místo a čas vyzvednutí nebo vrácení. Cena za přistavení/odvoz se počítá podle vzdálenosti od pobočky Mezná (1 000 Kč základ + 40 Kč/km). Rozdíl se vrací 100 % bez ohledu na čas, nový poplatek doplatíte přes Stripe.', 'web') ON CONFLICT (key) DO NOTHING;
INSERT INTO cms_variables (key, value, category) VALUES ('web.layout.editRez.loc.helpActive', 'Probíhající rezervaci už můžete měnit jen na straně vrácení (motorku máte vyzvednutou). Místo a čas vrácení lze upravit kdykoliv — rozdíl ceny dorovnáme automaticky.', 'web') ON CONFLICT (key) DO NOTHING;
